from pathlib import Path
import shutil,json,csv,zipfile
from decimal import Decimal
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4
from pypdf import PdfReader

BASE=Path(__file__).resolve().parent
SOURCE=BASE/'grade-complete-specimen-v3'
ROOT=BASE/'A-E-financial-scenarios';ROOT.mkdir(exist_ok=True)
DESCRIPTIONS={
'A':dict(title='Financially stable - strong capacity',summary='A salaried applicant receives LKR 200,000 every month. Existing loan repayments are only LKR 20,000, all facilities are current, and the account retains a substantial cash buffer. The requested LKR 20,000 lease installment is comfortably affordable.',bank='Six equal monthly salary credits of LKR 200,000, LKR 20,000 monthly debt repayments, routine personal expenses and own-account savings transfers. The statement opens and closes each month at LKR 160,000. No overdraft occurs.',crib='Synthetic bureau grade A1. Two active individually owned facilities with monthly installments of LKR 12,000 and LKR 8,000. No current arrears or adverse repayment history; a prior facility was settled normally.',why='Combined debt plus lease is 20% of income, earning the best debt-service tier. Stable income earns 25 points, the daily average balance covers more than six lease installments, and verified credit family A earns 20 points. No penalties apply.',lesson='Use this as the baseline financially stable case. A large own-account transfer is saving movement, not a living expense or a reduction of verified salary.'),
'B':dict(title='Financially sound - moderate commitments',summary='A salaried applicant receives LKR 150,000 monthly and repays LKR 25,000 of existing loans. Repayments are timely, but the cash buffer and debt burden are weaker than in scenario A. A LKR 20,000 lease remains manageable.',bank='Six equal monthly salary credits of LKR 150,000, monthly debt payments of LKR 25,000 and regular living expenses. Each month opens and closes at LKR 80,000. There are no overdrafts.',crib='Synthetic bureau grade B1. Active monthly installments are LKR 15,000 and LKR 10,000. No current arrears; repayment history is current and the closed facility was settled.',why='Combined debt plus lease is 30% of income, giving 25 debt-service points. Stable income contributes 25 points, an approximately four-installment cash buffer contributes 15, and credit family B contributes 15. Total: 80.',lesson='B is still financially sound. It has less capacity and liquidity than A, but does not need a high-risk label merely because debt exists.'),
'C':dict(title='Borderline - irregular repayment behaviour',summary='A salaried applicant receives LKR 100,000 monthly and already pays LKR 25,000 toward loans. Adding the LKR 20,000 lease uses 45% of income. The credit report shows irregular repayment history, including a prior 35-day delinquency and a current 15-day arrears record.',bank='Six equal monthly salary credits of LKR 100,000 and LKR 25,000 in monthly debt payments. The opening and closing balance is LKR 80,000. Salary is stable; the weakness here is repayment behaviour and combined commitments.',crib='Synthetic bureau grade C1. Monthly installments are LKR 15,000 and LKR 10,000. Facility 1 has LKR 7,500 arrears and current NDIA of 15 days; the highest NDIA in the twelve-month profile is 35 days. Facility 2 is current.',why='Combined commitments of 45% of income earn only 10 debt-service points. Income consistency earns 25, liquidity earns 15, and credit family C earns 5. No default penalty is assumed. Total: 55.',lesson='The 60% capacity test passes, yet repayment irregularities and weaker debt-service scoring lead to manual review. Passing affordability does not establish low credit risk.'),
'D':dict(title='High risk - heavy debt and serious arrears',summary='A salaried applicant receives LKR 100,000 monthly and owes LKR 35,000 in monthly installments. The proposed LKR 20,000 lease takes combined commitments to 55% of income. A facility is 95 days in arrears with LKR 63,000 overdue.',bank='Six monthly salary credits of LKR 100,000 and LKR 35,000 of regular monthly debt payments. Each month opens and closes at LKR 80,000. Current autopay records can coexist with unpaid historic arrears; the bank payments do not clear the credit report automatically.',crib='Synthetic bureau grade D1. Installments are LKR 21,000 and LKR 14,000. Facility 1 reports LKR 63,000 arrears and current NDIA of 95 days. Its evidence-window delinquency worsens from 30 to 95 days. No historical default boolean is inferred solely from the days-in-arrears value.',why='A 55% combined payment ratio earns zero debt-service points. Stable income earns 25, liquidity earns 15, and credit family D earns zero. The explicit verified fixture assumption sets default history to false. Total: 40.',lesson='Capacity still passes the configured 60% rule, but serious credit risk produces Escalate. D is not safe merely because its payment ratio is below 60%.'),
'E':dict(title='Financially unsuitable - over capacity with default history',summary='A salaried applicant receives LKR 80,000 monthly but already repays LKR 40,000. Adding a LKR 20,000 lease consumes 75% of income, exceeding the 60% cap. Current severe arrears and a historical written-off facility add major risk.',bank='Six monthly salary credits of LKR 80,000 and LKR 40,000 in existing debt payments. Each month opens and closes at LKR 35,000. The daily average balance is much smaller than in the other scenarios. No overdraft is needed for this applicant to be financially unsuitable.',crib='Synthetic bureau grade E1. Active monthly installments are LKR 24,000 and LKR 16,000. Facility 1 has LKR 72,000 arrears and current NDIA of 120 days. A previously closed facility has a synthetic LKR 50,000 write-off; the tester verifies default history as true.',why='Combined payments of 75% earn zero debt-service points. Stable income earns 25 and liquidity earns 5, while credit family E earns zero. The default penalty subtracts 50; the score is clamped to zero. The capacity rule also fails by LKR 12,000 per month.',lesson='Grade E can occur despite a regular salary and a positive bank balance. Excessive obligations and verified adverse history drive the result.'),
}
styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='SmallBody',parent=styles['BodyText'],fontSize=9,leading=13,spaceAfter=8));styles.add(ParagraphStyle(name='Cell',fontSize=8,leading=11));styles['Heading1'].textColor=colors.HexColor('#183e54');styles['Heading2'].textColor=colors.HexColor('#183e54')
P=lambda s:Paragraph(s,styles['SmallBody'])
story=[Paragraph('A-E financial-stability test scenarios',styles['Title']),P('Five paired cases, one per project lease-feasibility grade. All documents and identities are synthetic. Each case contains a six-month bank statement, a ten-page CRIB-style report, an explanation and verified expected inputs.'),P('The project lease grade and the bureau risk subgrade are different fields. These selected cases use bureau A1, B1, C1, D1 and E1 as representative inputs; their expected lease outcomes were checked against the actual project C# engine.'),Spacer(1,12)]
summary=[['Lease grade','Scenario','Income / month','Debt / month','Score / action']]
manifest=[]
for grade,desc in DESCRIPTIONS.items():
 source=SOURCE/(grade+'1');folder=ROOT/('Grade_'+grade);folder.mkdir(exist_ok=True)
 for old,new in [('bank_statement.pdf','Grade_'+grade+'_Bank_Statement.pdf'),('crib_report.pdf','Grade_'+grade+'_CRIB_Report.pdf')]:shutil.copy2(source/old,folder/new)
 data=json.loads((source/'expected.json').read_text());data['pack_scenario_id']='Grade_'+grade;data['scenario_description']=desc
 (folder/'expected.json').write_text(json.dumps(data,indent=2));manifest.append(data)
 a=data['verified_input_assumptions'];r=data['expected_result'];income=Decimal(a['AverageMonthlyIncomeLkr']);debt=Decimal(a['MonthlyDebtObligationsLkr']);lease=Decimal(a['RequestedMonthlyLeasePaymentLkr']);balance=Decimal(a['AverageAccountBalanceLkr'])
 assert r['lease_grade']==grade
 metrics=[('Monthly verified income',f'LKR {income:,.2f}'),('Existing monthly debt repayments',f'LKR {debt:,.2f}'),('Requested monthly lease',f'LKR {lease:,.2f}'),('Debt + lease / income',f'{(debt+lease)/income*100:.0f}%'),('Daily average bank balance',f'LKR {balance:,.2f}'),('60% maximum total monthly payments',f'LKR {Decimal(r["maximum_total_payments_lkr"]):,.2f}'),('Available monthly lease capacity',f'LKR {Decimal(r["available_lease_lkr"]):,.2f}'),('Bureau subgrade (synthetic)',data['bureau_subgrade']),('Project lease grade / total score',f'{grade} / {r["total_score"]}'),('Expected action',r['action'])]
 text='# Grade '+grade+' - '+desc['title']+'\n\n'+desc['summary']+'\n\n'
 for label,value in metrics:text+=f'- {label}: {value}\n'
 for label,key in [('Bank statement evidence','bank'),('CRIB report evidence','crib'),('Why this grade','why'),('What this scenario tests','lesson')]:text+='\n## '+label+'\n\n'+desc[key]+'\n'
 text+='\nIncome consistency and default history are explicit reviewer-verified fixture inputs. Savings transfers are not expenses. Bureau scores are assigned test values; these documents do not imply official approval or live OCR success.\n'
 (folder/'SCENARIO_DESCRIPTION.md').write_text(text)
 summary.append([grade,desc['title'],f'{income:,.0f}',f'{debt:,.0f}',f'{r["total_score"]} / {r["action"]}'])
 data['_display_metrics']=metrics
summary=[[Paragraph(str(v),styles['Cell']) for v in row] for row in summary]
t=Table(summary,colWidths=[48,155,82,82,138]);t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#eaf0f3')),('VALIGN',(0,0),(-1,-1),'TOP'),('GRID',(0,0),(-1,-1),.4,colors.HexColor('#ccd6dc')),('TOPPADDING',(0,0),(-1,-1),8),('BOTTOMPADDING',(0,0),(-1,-1),8)]));story += [t,Spacer(1,16),P('Every case requests a LKR 20,000 monthly lease payment. A and B are financially sound, C needs manual review, D has serious credit risk despite passing the capacity rule, and E both exceeds capacity and has verified default history.'),P('How to test: select one grade folder, upload its bank and CRIB PDFs, review the extracted inputs, then compare your result with expected.json. The lease request is provided separately in expected.json. Existing debt must come from verified monthly installments, never outstanding principal.'),P('Validation: bank totals, running balances and daily averages were checked. The actual C# scoring engine matched all five representative cases. Live OCR and end-to-end extraction remain untested.')]
for data in manifest:
 grade=data['expected_result']['lease_grade'];desc=data['scenario_description'];story += [PageBreak(),Paragraph('Grade '+grade+' - '+desc['title'],styles['Heading1']),P(desc['summary'])]
 metrics=data.pop('_display_metrics');t=Table([[Paragraph(label,styles['Cell']),Paragraph(value,styles['Cell'])] for label,value in metrics],colWidths=[285,220]);t.setStyle(TableStyle([('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,-1),.35,colors.HexColor('#d6dfe4')),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]));story += [t,Spacer(1,10)]
 for label,key in [('Bank statement evidence','bank'),('CRIB report evidence','crib'),('Why this grade','why'),('What to test','lesson')]:story += [Paragraph(label,styles['Heading2']),P(desc[key])]
def footer(c,doc):
 c.setFont('Helvetica',7);c.setFillColor(colors.HexColor('#777777'));c.drawString(45,24,'SYNTHETIC TEST SCENARIOS | Fictional data | LKR');c.drawRightString(550,24,f'Page {doc.page}')
SimpleDocTemplate(str(ROOT/'A-E_Scenario_Descriptions.pdf'),pagesize=A4,rightMargin=45,leftMargin=45,topMargin=40,bottomMargin=43).build(story,onFirstPage=footer,onLaterPages=footer)
assert len(PdfReader(ROOT/'A-E_Scenario_Descriptions.pdf').pages)==6
(ROOT/'manifest.json').write_text(json.dumps(manifest,indent=2))
(ROOT/'README.md').write_text('Five project lease-feasibility scenarios: Grade_A through Grade_E. Each folder contains its paired bank/CRIB PDFs, SCENARIO_DESCRIPTION.md and expected.json. Read A-E_Scenario_Descriptions.pdf for the complete explanation. The reports retain their fictional A1/B1/C1/D1/E1 bureau subgrades and identity labels from the verified source pack. These are representative cases, not a universal bureau-to-lease-grade mapping. No real personal information is used.\n')
engine=json.loads((SOURCE/'engine_validation.json').read_text());engine['results']=[r for r in engine['results'] if r['bureau_subgrade'] in [g+'1' for g in 'ABCDE']];engine['scenarios_scored']=5
(ROOT/'engine_validation.json').write_text(json.dumps(engine,indent=2))
for g in 'ABCDE':
 folder=ROOT/('Grade_'+g)
 assert len(PdfReader(folder/f'Grade_{g}_Bank_Statement.pdf').pages)==6
 assert len(PdfReader(folder/f'Grade_{g}_CRIB_Report.pdf').pages)==10
 with zipfile.ZipFile(ROOT/f'Grade_{g}_Documents.zip','w',zipfile.ZIP_DEFLATED) as z:
  for f in sorted(folder.iterdir()):z.write(f,f.relative_to(ROOT))
with zipfile.ZipFile(BASE/'A-E-financial-scenarios.zip','w',zipfile.ZIP_DEFLATED) as z:
 for f in sorted(ROOT.rglob('*')):
  if f.is_file():z.write(f,f.relative_to(BASE))
print('Created 5 grade folders, 10 paired financial PDFs, 5 individual ZIPs and a 6-page scenario guide.')
